return (async () => {
const asks = $('Parse: updates').all().map((i) => i.json).filter((u) => u.kind === 'taskaction');
const SB = String($env.SUPABASE_URL || '').replace(/\/$/, '');
const KEY = String($env.SUPABASE_SERVICE_ROLE_KEY || '');
const TENANT = String($env.OFFICE_TENANT_ID || '');
